<?php $labels=array('whatsapp'=>'WhatsApp','instagram'=>'Instagram','messenger'=>'Facebook Messenger');$inbox_channel=$inbox_channel??($channel==='whatsapp'?'whatsapp':'instagram');$label=$labels[$inbox_channel]??'WhatsApp';$inbox_extra=array('inbox_channel'=>$inbox_channel); ?>
<style>.comm-inbox-item{display:grid;grid-template-columns:minmax(150px,1fr) minmax(160px,2fr) auto;gap:16px;padding:18px 0;border-bottom:1px solid var(--cl);align-items:center}.comm-inbox-item p{margin:4px 0}.comm-message-list{display:flex;flex-direction:column;gap:14px;max-height:560px;overflow-y:auto;padding:14px;background:#f7f8fb;border-radius:12px}.comm-message{max-width:80%;padding:14px;border-radius:14px;background:white;border:1px solid var(--cl);overflow-wrap:anywhere;white-space:pre-wrap}.comm-message.outbound{align-self:flex-end;background:#efebfd}.comm-message.inbound{align-self:flex-start}.comm-message small{display:block;white-space:normal;margin-top:8px;color:var(--cm);font-size:10px}.comm-mobile .comm-inbox-item{grid-template-columns:1fr}.comm-mobile .comm-message{max-width:92%}</style>
<?php if(empty($can_inbox)): ?><section class="comm-card"><h2>Inbox access</h2><p class="muted">Ask your Administrator for permission to view customer conversations.</p></section><?php return;endif; ?>
<?php if($channel==='socials'): ?><nav class="comm-toolbar" aria-label="Social inbox channel"><?php foreach(array('instagram','messenger') as $social): ?><a class="btn <?= $inbox_channel===$social?'':'secondary'; ?>" href="<?= $h($workspace_url($workspace_section==='connection'?'connection':'inbox',array('inbox_channel'=>$social))); ?>"><?= $h($labels[$social]); ?></a><?php endforeach; ?></nav><?php endif; ?>
<?php if($workspace_section==='connection'): ?><section class="comm-card"><h2><?= $h($label); ?> connection</h2><span class="comm-badge <?= !empty($inbox_connection['configured'])?'ok':'off'; ?>"><?= !empty($inbox_connection['configured'])?'Configured':'Not configured'; ?></span><p class="muted"><?= !empty($inbox_connection['configured'])?'Your existing connection is available for customer conversations.':'Contact your Administrator to check your account connection. Existing conversation history is preserved.'; ?></p><a class="btn secondary" href="<?= $h($workspace_url('inbox',$inbox_extra)); ?>">Open inbox</a></section><?php return;endif; ?>
<?php if(empty($inbox_ready)): ?><section class="comm-card"><h2>Your conversation history</h2><p class="muted">The inbox is not available yet. Contact your Administrator to complete the update. Your existing conversations have not been deleted.</p></section><?php return;endif; ?>
<?php if(empty($inbox_connection['configured'])): ?><div class="notice"><?= $h($label); ?> is not configured. You can read existing messages; contact your Administrator to restore replies.</div><?php endif; ?>
<?php if($workspace_section==='conversation' && !empty($conversation)): ?>
<section class="comm-card"><div class="comm-head"><div><h2><?= $h($conversation['customer_name']?:($conversation['customer_phone']?:'Customer')); ?></h2><p class="muted"><?= $h($label); ?> · <?= $h($conversation['customer_phone']??''); ?> · <?= $h(ucfirst($conversation['status'])); ?></p></div><a class="btn secondary" href="<?= $h($workspace_url('inbox',$inbox_extra)); ?>">Back to inbox</a></div>
<?php $rows=$inbox_messages??array();$hasOlder=count($rows)>100;$rows=array_slice($rows,0,100);if($hasOlder): ?><p><a href="<?= $h($workspace_url('conversation',array_merge($inbox_extra,array('conversation'=>$conversation['id'],'before'=>min(array_column($rows,'id')))))); ?>">Load older messages</a></p><?php endif; ?>
<div class="comm-message-list" id="comm-message-list"><?php foreach(array_reverse($rows) as $message): ?><div class="comm-message <?= $message['direction']==='outbound'?'outbound':'inbound'; ?>"><?= $h($message['body']?:'(no text)'); ?><small><?= $h(ucfirst($message['direction'])); ?> · <?= $h($message['created_at']); ?> · <?= $h(ucfirst($message['status']??'')); ?></small></div><?php endforeach; ?><?php if(!$rows): ?><p class="empty">No messages in this conversation yet.</p><?php endif; ?></div>
<?php if(!empty($can_reply) && !empty($inbox_connection['configured'])): ?><?= form_open('communications/inbox_reply',array('id'=>'comm-inbox-reply')); ?><input type="hidden" name="conversation_id" value="<?= (int)$conversation['id']; ?>"><input type="hidden" name="inbox_channel" value="<?= $h($inbox_channel); ?>"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><input type="hidden" name="request_key" value="<?= $h(bin2hex(random_bytes(20))); ?>"><label>Your reply<textarea name="text" rows="3" maxlength="4000" required></textarea></label><button class="btn" style="margin-top:14px">Send reply</button><?= form_close(); ?><?php elseif(empty($can_reply)): ?><p class="muted">You have read-only inbox access. Ask your Administrator for reply permission.</p><?php endif; ?></section>
<?php else: ?><section class="comm-card"><h2><?= $h($label); ?> conversations</h2><?php $list=$conversations??array();$more=count($list)>50;foreach(array_slice($list,0,50) as $thread): ?><article class="comm-inbox-item"><div><b><?= $h($thread['customer_name']?:($thread['customer_phone']?:'Customer')); ?></b><p class="muted"><?= $h($thread['customer_phone']??''); ?> · <?= $h(ucfirst($thread['status'])); ?></p></div><div><p><?= $h(mb_substr((string)($thread['preview']??''),0,160)); ?></p><small class="muted"><?= $h($thread['last_message_at']??''); ?></small></div><a class="btn secondary" href="<?= $h($workspace_url('conversation',array_merge($inbox_extra,array('conversation'=>$thread['id'])))); ?>">Open conversation</a></article><?php endforeach; ?><?php if(!$list): ?><p class="empty">No <?= $h($label); ?> conversations yet. Customer messages appear here through your existing connection.</p><?php endif; ?><div class="row" style="margin-top:18px"><?php if(!empty($inbox_page)): ?><a href="<?= $h($workspace_url('inbox',array_merge($inbox_extra,array('inbox_page'=>$inbox_page-1)))); ?>">Newer conversations</a><?php endif; ?><?php if($more): ?><a href="<?= $h($workspace_url('inbox',array_merge($inbox_extra,array('inbox_page'=>($inbox_page??0)+1)))); ?>">Older conversations</a><?php endif; ?></div></section><?php endif; ?>
